from __future__ import annotations

import json
import logging
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

from .models import Area, TimeWindow, TimeZoneRule

logger = logging.getLogger("zk.rules")


class AccessRulesRegistry:
    """
    Manages in-memory (with optional JSON persistence) logical access control mappings:
        Area -> TimeZoneRule
        user_id -> Area

    Since standalone ZKTeco devices (using pyzk protocol) do not natively enforce
    complex time schedules / areas on-device (this is a feature of C3/ZKAccess pull-SDK panels),
    this registry provides the application-level logic to evaluate whether a live capture event
    is within the permitted schedule for the user's assigned area.
    """

    def __init__(self, storage_path: Optional[Union[str, Path]] = None):
        self.storage_path = Path(storage_path) if storage_path else None
        self.time_zones: Dict[str, TimeZoneRule] = {}
        self.areas: Dict[str, Area] = {}
        self.user_area_map: Dict[str, str] = {}  # user_id (str) -> area_name

        if (
            self.storage_path
            and self.storage_path.exists()
            and self.storage_path.stat().st_size > 0
        ):
            self.load()

    def define_time_zone(
        self,
        name: str,
        windows: List[Union[Tuple[Optional[int], str, str], TimeWindow, dict]],
    ) -> TimeZoneRule:
        """
        Define or update a named time zone rule.

        `windows`: List of (weekday, "HH:MM", "HH:MM") tuples, dicts, or TimeWindow objects.
        Example:
            [(None, "08:00", "18:00")] -> Monday to Sunday, 08:00 to 18:00.
            [(0, "08:00", "12:00"), (0, "13:00", "18:00")] -> Mondays only, two shifts.
        """
        parsed_windows: List[TimeWindow] = []
        for w in windows:
            if isinstance(w, TimeWindow):
                parsed_windows.append(w)
            elif isinstance(w, dict):
                parsed_windows.append(TimeWindow(**w))
            elif isinstance(w, (tuple, list)) and len(w) == 3:
                parsed_windows.append(TimeWindow(weekday=w[0], start=w[1], end=w[2]))
            else:
                raise ValueError(f"Invalid window format: {w}")

        tz = TimeZoneRule(name=name, windows=parsed_windows)
        self.time_zones[name] = tz
        logger.debug(
            "TimeZone rule '%s' defined with %d windows.", name, len(tz.windows)
        )
        return tz

    def remove_time_zone(self, name: str) -> None:
        """Remove a time zone rule."""
        self.time_zones.pop(name, None)
        # Clear reference from areas using it
        for area in self.areas.values():
            if area.time_zone == name:
                area.time_zone = None

    def define_area(
        self,
        name: str,
        time_zone: Optional[str] = None,
        description: str = "",
    ) -> Area:
        """
        Define or update a logical area associated with a time zone rule.
        """
        if time_zone and time_zone not in self.time_zones:
            raise ValueError(
                f"TimeZone rule '{time_zone}' does not exist. Define it first with define_time_zone()."
            )

        area = Area(name=name, time_zone=time_zone, description=description)
        self.areas[name] = area
        logger.debug(
            "Area '%s' defined (time zone: %s).", name, time_zone or "unrestricted"
        )
        return area

    def remove_area(self, name: str) -> None:
        """Remove an area and unassign users linked to it."""
        self.areas.pop(name, None)
        unlinked = [uid for uid, aname in self.user_area_map.items() if aname == name]
        for uid in unlinked:
            self.user_area_map.pop(uid, None)

    def assign_user_to_area(self, user_id: Union[str, int], area_name: str) -> None:
        """Assign a user_id to a specific logical area."""
        if area_name not in self.areas:
            raise ValueError(
                f"Area '{area_name}' does not exist. Define it first with define_area()."
            )
        self.user_area_map[str(user_id)] = area_name
        logger.debug("User %s assigned to area '%s'.", user_id, area_name)

    def unassign_user(self, user_id: Union[str, int]) -> None:
        """Remove user area assignment."""
        self.user_area_map.pop(str(user_id), None)

    def get_user_area(self, user_id: Union[str, int]) -> Optional[Area]:
        """Return the Area assigned to a user, or None."""
        area_name = self.user_area_map.get(str(user_id))
        return self.areas.get(area_name) if area_name else None

    def is_access_allowed(
        self, user_id: Union[str, int], when: Optional[datetime] = None
    ) -> bool:
        """
        Evaluate if an access event by user_id at the specified datetime is allowed.
        Returns True if:
          - User has no area assigned (unrestricted access)
          - Area has no time zone assigned (unrestricted access)
          - Access occurs within one of the TimeWindow intervals of the associated TimeZoneRule
        """
        when = when or datetime.now()
        area = self.get_user_area(user_id)
        if area is None or area.time_zone is None:
            return True

        tz = self.time_zones.get(area.time_zone)
        if tz is None:
            return True

        return tz.is_allowed(when)

    def save(self, path: Optional[Union[str, Path]] = None) -> None:
        """Serialize rules to a JSON file."""
        target_path = Path(path) if path else self.storage_path
        if not target_path:
            raise ValueError("No storage_path defined to save access rules.")

        target_path.parent.mkdir(parents=True, exist_ok=True)
        data = {
            "time_zones": {
                name: [w.model_dump() for w in tz.windows]
                for name, tz in self.time_zones.items()
            },
            "areas": {name: area.model_dump() for name, area in self.areas.items()},
            "user_area_map": self.user_area_map,
        }
        target_path.write_text(
            json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8"
        )
        logger.info("Access rules successfully saved to %s.", target_path)

    def load(self, path: Optional[Union[str, Path]] = None) -> None:
        """Load rules from a JSON file."""
        target_path = Path(path) if path else self.storage_path
        if not target_path or not target_path.exists():
            raise FileNotFoundError(f"Access rules file not found at: {target_path}")

        data = json.loads(target_path.read_text(encoding="utf-8"))
        self.time_zones = {}
        for name, windows_data in data.get("time_zones", {}).items():
            self.define_time_zone(name, windows_data)

        self.areas = {}
        for name, area_data in data.get("areas", {}).items():
            self.define_area(
                name=name,
                time_zone=area_data.get("time_zone"),
                description=area_data.get("description", ""),
            )

        self.user_area_map = data.get("user_area_map", {})
        logger.info("Access rules successfully loaded from %s.", target_path)
